node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { loadVendorFile } from './tools/node-vendor.mjs';
loadVendorFile('compiler/typed/tape.js');
loadVendorFile('compiler/typed/typed-wasm.js');
const source = \`
function inRange(c: i32, lo: i32, hi: i32): bool { return lo <= c && c <= hi; }
function probe(b: buffer): i32 {
  const a = new Int32Array(16);
  for (let i = 0; i < b.length && i < 16; i = i + 1) {
    const c = b.charCodeAt(i);
    if (!inRange(c, 97, 99)) { continue; }
    a[i] = c;
  }
  let j = 0;
  while (j < 16) {
    if (a[j] > 0) { break; }
    j = j + 1;
  }
  return j;
}
\`;
const events = [];
const artifact = globalThis.typedWasm.compile(source, { inspect: { emit: event => events.push(event) } });
assert(WebAssembly.validate(artifact.bytes));
const tape = JSON.stringify(events);
for (const op of ['array.zero', 'array.address', 'text.checked_address', 'i32.load16_u', 'i32.store', 'call', 'br_if']) assert(tape.includes(op), op);
console.log('Typed feature probe compiled and emitted the frame, buffer, call and branch ops.');
const matches = (pattern, text) => Number(new RegExp("^(?:" + pattern + ")(?![\\s\\S])").test(text));
const cases = [
  ['', '', 1], ['', 'a', 0],
  ['ab|c', 'ab', 1], ['ab|c', 'c', 1], ['ab|c', 'ac', 0], ['ab|c', 'abc', 0],
  ['a*', '', 1], ['a*', 'aaa', 1], ['a*', 'aa\n', 0],
  ['(a*)*', '', 1], ['(a*)*', 'aaa', 1], ['(a*)*', 'b', 0],
  ...[0,1,1,1,0].map((result, i) => ['[b-d]', 'abcde'[i], result]),
  ['([a-c]|[b-d])*', 'bcdd', 1],
  ['(a|[b-c])*d', 'd', 1], ['(a|[b-c])*d', 'abccd', 1], ['(a|[b-c])*d', 'abcc', 0], ['(a|[b-c])*d', 'd\n', 0],
  ['a', String.fromCharCode(0), 0], ['a', String.fromCharCode(55296, 56320), 0],
  ['(abcdefghijklmn)', 'abcdefghijkl', 0],
  ['a*a*a*a*a*', 'a'.repeat(12), 1],
];
for (const [pattern, input, expected] of cases) assert.equal(matches(pattern, input), expected, JSON.stringify([pattern, input]));
console.log(\`RegExp agreed with all \${cases.length} directed in-domain match/miss expectations.\`);
JS

node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { registerHooks } from 'node:module';
import { loadVendorFile } from './tools/node-vendor.mjs';
registerHooks({resolve(specifier, context, next) {
  if (context.parentURL?.includes('/src/') && specifier.startsWith('.') && specifier.endsWith('.js'))
    return next(specifier.slice(0, -3) + '.ts', context);
  return next(specifier, context);
}});
loadVendorFile('compiler/typed/tape.js');
loadVendorFile('compiler/typed/typed-wasm.js');
const { setVendor } = await import('./src/typed/vendor.ts');
setVendor({typedWasm: globalThis.typedWasm, typedTape: globalThis.typedTape});
const { ingest } = await import('./src/typed/lift.ts');
const { evaluate, benchCase } = await import('./src/typed/evaluate.ts');
const source = \`
function inRange(c: i32, lo: i32, hi: i32): bool { return lo <= c && c <= hi; }
function probe(b: buffer): i32 {
  const a = new Int32Array(16);
  for (let i = 0; i < b.length && i < 16; i = i + 1) {
    const c = b.charCodeAt(i);
    if (!inRange(c, 97, 99)) { continue; }
    a[i] = c;
  }
  let j = 0;
  while (j < 16) {
    if (a[j] > 0) { break; }
    j = j + 1;
  }
  return j;
}
\`;
assert.throws(() => ingest('probe', source), /unknown tape opcode 252/);
const store = ingest('probe', source, {tape: true});
assert.equal(store.fn('probe').arrayBytes, 64);
const c = benchCase(store, 'probe', {b: {string: 'za'}});
const run = evaluate(store, 'probe', c.args, c.memory, {limit: 2e4});
assert.equal(run.trap, false);
assert.equal(run.result, 1);
assert.deepEqual(run.bytes, c.memory);
console.log(\`Default ingest reproduces opcode 252. Tape ingest and evaluation succeed (\${run.steps} statements).\`);
const matches = (p, t) => Number(new RegExp("^(?:" + p + ")(?![\\s\\S])").test(t));
const cases = [
  ['', '', 1], ['', 'a', 0],
  ['ab|c', 'ab', 1], ['ab|c', 'c', 1], ['ab|c', 'ac', 0], ['ab|c', 'abc', 0],
  ['a*', '', 1], ['a*', 'aaa', 1], ['a*', 'aa\n', 0],
  ['(a*)*', '', 1], ['(a*)*', 'aaa', 1], ['(a*)*', 'b', 0],
  ...[0,1,1,1,0].map((result, i) => ['[b-d]', 'abcde'[i], result]),
  ['([a-c]|[b-d])*', 'bcdd', 1],
  ['(a|[b-c])*d', 'd', 1], ['(a|[b-c])*d', 'abccd', 1], ['(a|[b-c])*d', 'abcc', 0], ['(a|[b-c])*d', 'd\n', 0],
  ['a', String.fromCharCode(0), 0], ['a', String.fromCharCode(55296, 56320), 0],
  ['(abcdefghijklmn)', 'abcdefghijkl', 0],
  ['a*a*a*a*a*', 'a'.repeat(12), 1],
];
for (const [p, t, expected] of cases) assert.equal(matches(p, t), expected, JSON.stringify([p, t]));
console.log(\`RegExp agreed with all \${cases.length} directed in-domain match/miss expectations.\`);
JS

node --experimental-transform-types --disable-warning=ExperimentalWarning --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { registerHooks } from 'node:module';
import { loadVendorFile } from './tools/node-vendor.mjs';
registerHooks({resolve(s, c, next) {
  return next(c.parentURL?.includes('/src/') && s.startsWith('.') && s.endsWith('.js') ? s.slice(0,-3) + '.ts' : s, c);
}});
for (const file of ['tape.js','typed-wasm.js','typed-rv32.js']) loadVendorFile('compiler/typed/' + file);
loadVendorFile('bench/host/rv32-interp.js');
const {setVendor} = await import('./src/typed/vendor.ts');
setVendor({typedWasm: globalThis.typedWasm, typedTape: globalThis.typedTape, typedRv32: globalThis.typedRv32, typedRv32Interp: globalThis.typedRv32Interp});
const {ingest} = await import('./src/typed/lift.ts');
const {evaluate, benchCase, agrees} = await import('./src/typed/evaluate.ts');
const {referenceCompile, referenceRun} = await import('./src/typed/reference.ts');
const source = \`
function inRange(c: i32, lo: i32, hi: i32): bool { return lo <= c && c <= hi; }
function probe(b: buffer): i32 {
  const a = new Int32Array(16);
  for (let i = 0; i < b.length && i < 16; i = i + 1) {
    const c = b.charCodeAt(i);
    if (!inRange(c, 97, 99)) { continue; }
    a[i] = c;
  }
  let j = 0;
  while (j < 16) {
    if (a[j] > 0) { break; }
    j = j + 1;
  }
  return j;
}\`;
assert.throws(() => ingest('probe', source), /unknown tape opcode 252/);
const store = ingest('probe', source, {tape: true});
assert.equal(store.fn('probe').arrayBytes, 64);
const c = benchCase(store, 'probe', {b: {string: 'za'}});
const run = evaluate(store, 'probe', c.args, c.memory, {limit: 2e4});
assert.equal(run.trap, false);
assert.equal(run.result, 1);
assert.deepEqual(run.bytes, c.memory);
assert(agrees(run, referenceRun(referenceCompile(source), 'probe', c.args, c.memory)));
console.log(\`Default ingest reproduces opcode 252. Tape ingest, evaluator (\${run.steps} statements) and stock reference image agree.\`);
const matches = (p, t) => Number(new RegExp("^(?:" + p + ")(?![\\s\\S])").test(t));
const cases = [
  ['', '', 1], ['', 'a', 0],
  ['ab|c', 'ab', 1], ['ab|c', 'c', 1], ['ab|c', 'ac', 0], ['ab|c', 'abc', 0],
  ['a*', '', 1], ['a*', 'aaa', 1], ['a*', 'aa\n', 0],
  ['(a*)*', '', 1], ['(a*)*', 'aaa', 1], ['(a*)*', 'b', 0],
  ...[0,1,1,1,0].map((r, i) => ['[b-d]', 'abcde'[i], r]),
  ['([a-c]|[b-d])*', 'bcdd', 1],
  ['(a|[b-c])*d', 'd', 1], ['(a|[b-c])*d', 'abccd', 1], ['(a|[b-c])*d', 'abcc', 0], ['(a|[b-c])*d', 'd\n', 0],
  ['a', String.fromCharCode(0), 0], ['a', String.fromCharCode(55296,56320), 0],
  ['(abcdefghijklmn)', 'abcdefghijkl', 0], ['a*a*a*a*a*', 'a'.repeat(12), 1],
];
for (const [p,t,r] of cases) assert.equal(matches(p,t), r, JSON.stringify([p,t]));
console.log(\`RegExp agreed with all \${cases.length} directed in-domain match/miss expectations.\`);
JS
